CREATE TABLE public.buyer_ai_drafts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_id uuid NOT NULL REFERENCES public.contact_submissions(id), status text NOT NULL DEFAULT 'processing', subject text, body text, reason text, inventory_snapshot jsonb NOT NULL DEFAULT '[]', context_key text, error text, decided_by_name text, decided_by_user_id uuid, decided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, deleted_by uuid, UNIQUE(submission_id)); GRANT SELECT, UPDATE ON public.buyer_ai_drafts TO authenticated; GRANT ALL ON public.buyer_ai_drafts TO service_role; ALTER TABLE public.buyer_ai_drafts ENABLE ROW LEVEL SECURITY; CREATE POLICY buyer_ai_staff_read ON public.buyer_ai_drafts FOR SELECT TO authenticated USING ((public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff')) AND auth.uid() <> 'e07b4a4c-56d1-4b2f-bc27-7989314d008f'::uuid); CREATE POLICY buyer_ai_staff_update ON public.buyer_ai_drafts FOR UPDATE TO authenticated USING ((public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff')) AND auth.uid() <> 'e07b4a4c-56d1-4b2f-bc27-7989314d008f'::uuid) WITH CHECK ((public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff')) AND auth.uid() <> 'e07b4a4c-56d1-4b2f-bc27-7989314d008f'::uuid); CREATE TRIGGER zzz_prevent_hard_delete BEFORE DELETE ON public.buyer_ai_drafts FOR EACH ROW EXECUTE FUNCTION public.prevent_hard_delete();